#!/bin/bash
pip install duckdb-engine psycopg2-binary
if [ ! -f ~/bootstrap ]; then echo "Running Superset with uid {{ .Values.runAsUser }}" > ~/bootstrap; fi

ui = true
disable_mlock = true

listener "tcp" {
  tls_disable = 1
  address = "[::]:8200"
  cluster_address = "[::]:8201"

  telemetry {
    unauthenticated_metrics_access = "true"
  }
}

storage "raft" {
  path = "/openbao/data"
}

seal "gcpckms" {
  project     = "shiftx-399401"
  region      = "us-west1"
  key_ring    = "openbao-unseal"
  crypto_key  = "openbao-key"
  credentials = "/openbao/userconfig/openbao-gcp-kms/credentials.json"
}

service_registration "kubernetes" {}
